Example//Java program to print pyramid using for loop
public class Main {  
 public static void main(String[] args) {  
  for(int i=1;i<=5;i++){  
   for(int j=1;j<=i;j++){  
        System.out.print("* ");  
   }  
   System.out.println();//new line  
  }  
 }  
}  
Compile and Run

Example//Java program to print pyramid or star pattern using for loop
public class Main {  
 public static void main(String[] args) {  
  int term=6;  
  for(int i=1;i<=term;i++){  
   for(int j=term;j>=i;j--){  
        System.out.print("* ");  
   }  
  System.out.println();//new line  
  }  
 }  
}  
